    def _entries(self, old_counts=(1, 3, 5), size=6):
        leaves = self._leaves(size)
        return [
            MerkleConsistencyBatchEntry(
                merkle_root(leaves[:old_count]),
                merkle_root(leaves),
                prove_consistency(leaves, old_count),
